mapper.select:
SELECT FROM dangerous_area d LEFT JOIN trailgo_hazard_review r ON r.hazard_id = d.idx
AND (d.da_content LIKE CONCAT('%', #{keyword}, '%') OR d.da_addr LIKE CONCAT('%', #{keyword}, '%') OR d.da_rider LIKE CONCAT('%', #{keyword}, '%') OR r.title LIKE CONCAT('%', #{keyword}, '%'))
AND COALESCE(r.hazard_type, 'OTHER') = #{hazardType}
AND = #{status}
AND DATE(COALESCE(r.created_at, d.create_date, CURRENT_TIMESTAMP)) >= #{dateFrom}
AND DATE(COALESCE(r.created_at, d.create_date, CURRENT_TIMESTAMP)) <= #{dateTo}
AND COALESCE(r.report_count, 0) > 0
AND COALESCE(r.report_count, 0) = 0
ORDER BY COALESCE(r.created_at, d.create_date, CURRENT_TIMESTAMP) ASC, d.idx ASC ORDER BY COALESCE(r.created_at, d.create_date, CURRENT_TIMESTAMP) DESC, d.idx DESC
LIMIT 200

mapper.update:
UPDATE dangerous_area
da_latitude = #{latitude}, da_longitude = #{longitude}, da_addr = #{address}, da_content = #{description}, idx = idx
WHERE idx = #{id}

UPDATE trailgo_hazard_review
title = #{title}, hazard_type = #{hazardType}, updated_at = CURRENT_TIMESTAMP
WHERE hazard_id = #{id}

UPDATE trailgo_hazard_review
SET status = 'INACTIVE', is_active = 0, merged_into = #{targetId}, updated_at = CURRENT_TIMESTAMP
WHERE hazard_id = #{id}
